    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "search_existing_issues",
    "description": "Sucht in vorhandenen read-only GitHub-Issue-Snapshots. Schreibt nichts nach GitHub.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 20
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "find_candidate_issue_matches",
    "description": "Findet deterministische Kandidaten zwischen einem AcceptedIssuePlanItem und vorhandenen GitHub Issues.",
