              },
              "title": {
                "type": "string"
              },
              "body": {
                "type": "string"
              },
              "acceptanceCriteria": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "labels": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "reason": {
                "type": "string"
              },
              "requiresHumanReview": {
                "type": "boolean"
              },
              "metadata": {
                "type": "object"
              }
            },
            "required": [
              "actionId",
              "operation",
              "issuePlanId",
              "sourceRequirementIds",
              "targetIssueNumber",
              "title",
              "body",
              "acceptanceCriteria",
              "labels",
              "reason",
              "requiresHumanReview",
              "metadata"
