tags.gen_ai.input.messages:
[
  {
    "role": "user",
    "parts": [
      {
        "type": "text",
        "content": "Beginne jetzt mit plan-only GitHub Reconciliation.\n\nDu bekommst einen akzeptierten IssuePlan sowie optional vorhandene GitHub-Issue-Snapshots\nund lokale Mappings. Erzeuge daraus einen GitHubActionPlan.\n\nSchreibe nichts nach GitHub. Pruefe deinen Plan mit check_github_action_plan und speichere\ngenau einmal mit save_github_action_plan."
      }
    ]
  }
]

